// Server Component (no "use client") — this is what lets us read
// nour.svg off disk with `fs` and pass the derived chunk list down as
// plain props, instead of hardcoding a copy in client code.
import { NOUR_CHUNKS, NOUR_VIEWBOX, NOUR_STROKE_WIDTH } from "@/lib/nour-path";
import HomeClient from "./HomeClient";

export default function Page() {
  return (
    <HomeClient
      nourChunks={NOUR_CHUNKS}
      nourViewBox={NOUR_VIEWBOX}
      nourStrokeWidth={NOUR_STROKE_WIDTH}
    />
  );
}