import fs from "fs";
import path from "path";
import svgpath from "svgpath";

/**
 * Single source of truth for the wordmark: an ordered list of drawing
 * "chunks", its stroke weight, and the canvas to draw it on. Read
 * directly out of /public/nour.svg.
 *
 * nour.svg is a single <path>, fill="none" stroke="#000", made of 9
 * separate pen strokes (9 "M" moves) — a one-line hand-drawn signature
 * reading "Nour": N, then O, then U, then R.
 *
 * IMPORTANT — this was previously buggy in a few ways, all fixed here:
 *
 * 1. The strokes are NOT saved in a sensible draw order. A previous
 *    version of this file assumed they'd already been re-saved
 *    bottom-left-first, but the raw file order jumps around between
 *    letters (e.g. part of the "O" is drawn, then a stroke that belongs
 *    near the "N", etc). DRAW_ORDER below is an explicit, hand-verified
 *    sequence (found by mapping each of the 9 raw strokes to the letter
 *    it belongs to, then solving for the shortest-hop path through each
 *    letter group in turn: N -> O -> U -> R) so the pen genuinely
 *    travels left-to-right through the word instead of teleporting
 *    between letters. A couple of strokes are marked `reversed: true`
 *    because they connect more smoothly when drawn tail-first.
 *
 *    NOTE: DRAW_ORDER is tied to *this specific* nour.svg (its 9
 *    strokes, in their current raw order). If nour.svg is ever
 *    re-exported and the strokes change count or shape, this ordering
 *    needs to be re-derived — there's a sanity check below that throws
 *    a clear error if the stroke count no longer matches, rather than
 *    silently drawing the wrong thing.
 *
 * 2. The hand-drawn strokes have small real gaps between them (a few
 *    units up to ~20 units, e.g. between the "O" and the "U", and
 *    between each piece of the "R"). Three different approaches to this
 *    were tried and rejected before landing on the one below:
 *      a) Splicing a brand-new straight line across the gap — rejected,
 *         because that draws ink that was never in nour.svg.
 *      b) A silent, undrawn pause between two independently-timed paths
 *         — rejected, because with N separate <motion.path> elements on
 *         N separate timelines, tiny drift between them could make one
 *         path visibly start before/after the previous one's ink had
 *         actually finished painting — reading as the pen jumping ahead
 *         and a line snapping back to reconnect.
 *      c) Welding all 9 strokes into one continuous subpath with a
 *         straight "L" bridging every gap, animated with a single
 *         pathLength tween — this fixed the drift problem (only one
 *         path, so nothing to drift against) but brought back the
 *         "fabricated line" problem from (a): the bridge is still new
 *         ink that isn't part of the actual signature.
 *    Fixed properly here: each stroke that's followed by a real gap gets
 *    an extra "retrace" chunk — the same stroke, drawn again in reverse,
 *    going back over ink that's already on screen — followed by an
 *    "invisible jump" chunk straight to the next stroke's start, drawn
 *    with opacity permanently 0. This satisfies both constraints at
 *    once: nothing new is ever visibly drawn across blank canvas (the
 *    retrace only revisits pixels the pen has already inked, and the
 *    actual gap-crossing is never rendered at all), AND it's driftproof
 *    (every visible chunk's boundary is drawn at a *literal, identical*
 *    canvas coordinate as the chunk before it — a forward stroke and its
 *    own retrace share an endpoint by construction — so even if a chunk
 *    starts a frame early or late, there is no gap in space for that
 *    timing error to expose. The only points where drift genuinely could
 *    matter are made deliberately invisible instead.)
 *
 * 3. strokeLength() (and the walk that measures/reverses each stroke)
 *    only understood "M" and "C" commands. Two of the 9 strokes use an
 *    "L" (straight line) command, and one of them — the stem of the "R"
 *    — is *pure* M+L with no curve at all. That stroke was silently
 *    measured as zero-length, which meant it animated with ~0 duration
 *    and just popped in instantly instead of drawing. Fixed by parsing
 *    L segments alongside M/C everywhere length or endpoints are
 *    computed.
 *
 * Requires: npm install svgpath
 *
 * Runs server-side only (via fs) — do NOT import this from a "use client"
 * file. Call it from a Server Component (e.g. page.tsx) and pass the
 * results down as props.
 */

export type NourChunk = {
  d: string;        // this chunk's own path data
  length: number;   // approximate real arc length, in SVG user units — used for timing only
  visible: boolean; // false for the gap-crossing jump chunks: always rendered at opacity 0
};

// ---- read + normalize -----------------------------------------------

function readNourSvgRaw(): string {
  const svgFilePath = path.join(process.cwd(), "public", "nour.svg");
  return fs.readFileSync(svgFilePath, "utf-8");
}

function attr(tag: string, name: string): string | null {
  const m = tag.match(new RegExp(`${name}="([^"]*)"`));
  return m ? m[1] : null;
}

const svgContent = readNourSvgRaw();

const pathTagMatch = svgContent.match(/<path\b[^>]*>/);
if (!pathTagMatch) {
  throw new Error("nour.svg: no <path> element found.");
}
const pathTag = pathTagMatch[0];

const rawD = attr(pathTag, "d");
if (!rawD) {
  throw new Error("nour.svg: <path> has no d attribute.");
}

// This file's coordinates already have any transform baked in — but if
// you re-export from Inkscape and it adds one back, this still handles
// it rather than silently dropping it.
const rawTransform = attr(pathTag, "transform");
const rawStrokeWidth = attr(pathTag, "stroke-width");

let normalized = svgpath(rawD).abs();

if (rawTransform) {
  const translateMatch = rawTransform.match(
    /translate\(\s*(-?[\d.]+)[ ,]+(-?[\d.]+)\s*\)/
  );
  if (translateMatch) {
    normalized = normalized.translate(
      parseFloat(translateMatch[1]),
      parseFloat(translateMatch[2])
    );
  }
}

normalized = normalized.unshort();
const fullD = normalized.round(4).toString();

// ---- split into individual strokes, in raw file order -------------------

function splitIntoStrokes(d: string): string[] {
  const tokens = d.match(/[MC][^MC]*/g) ?? [];
  const strokes: string[] = [];
  let current = "";
  for (const tok of tokens) {
    if (tok[0] === "M") {
      if (current) strokes.push(current.trim());
      current = tok;
    } else {
      current += " " + tok;
    }
  }
  if (current) strokes.push(current.trim());
  return strokes;
}

// ---- point-level parsing (M / C / L) -------------------------------------
// Everything below understands straight-line ("L") segments as well as
// cubic curves — the old version only handled M/C, which is what silently
// zeroed out the R-stem stroke (a pure M+L path with no C in it at all).

type Point = { x: number; y: number };
type Segment =
  | { cmd: "L"; to: Point }
  | { cmd: "C"; cp1: Point; cp2: Point; to: Point };

function parseSegments(d: string): { start: Point; end: Point; segments: Segment[] } {
  const tokens = d.match(/[MCL][^MCL]*/g) ?? [];
  const nums = (s: string) => (s.match(/-?\d*\.?\d+(?:[eE][-+]?\d+)?/g) ?? []).map(Number);
  let start: Point = { x: 0, y: 0 };
  let cursor: Point = { x: 0, y: 0 };
  const segments: Segment[] = [];

  for (const tok of tokens) {
    const cmd = tok[0];
    const n = nums(tok.slice(1));
    if (cmd === "M") {
      cursor = { x: n[0], y: n[1] };
      start = { ...cursor };
    } else if (cmd === "C") {
      for (let i = 0; i + 5 < n.length; i += 6) {
        const to = { x: n[i + 4], y: n[i + 5] };
        segments.push({
          cmd: "C",
          cp1: { x: n[i], y: n[i + 1] },
          cp2: { x: n[i + 2], y: n[i + 3] },
          to,
        });
        cursor = to;
      }
    } else if (cmd === "L") {
      for (let i = 0; i + 1 < n.length; i += 2) {
        const to = { x: n[i], y: n[i + 1] };
        segments.push({ cmd: "L", to });
        cursor = to;
      }
    }
  }

  return { start, end: cursor, segments };
}

function cubicPoint(p0: Point, p1: Point, p2: Point, p3: Point, t: number): Point {
  const mt = 1 - t;
  return {
    x: mt * mt * mt * p0.x + 3 * mt * mt * t * p1.x + 3 * mt * t * t * p2.x + t * t * t * p3.x,
    y: mt * mt * mt * p0.y + 3 * mt * mt * t * p1.y + 3 * mt * t * t * p2.y + t * t * t * p3.y,
  };
}

function strokeLength(d: string): number {
  const { start, segments } = parseSegments(d);
  let cursor = start;
  let len = 0;
  for (const seg of segments) {
    if (seg.cmd === "L") {
      len += Math.hypot(seg.to.x - cursor.x, seg.to.y - cursor.y);
      cursor = seg.to;
    } else {
      const p0 = cursor;
      const samples = 20;
      let prev = p0;
      for (let s = 1; s <= samples; s++) {
        const pt = cubicPoint(p0, seg.cp1, seg.cp2, seg.to, s / samples);
        len += Math.hypot(pt.x - prev.x, pt.y - prev.y);
        prev = pt;
      }
      cursor = seg.to;
    }
  }
  return len;
}

function fmt(n: number): string {
  return String(Math.round(n * 10000) / 10000);
}

function buildD(start: Point, segments: Segment[]): string {
  let d = `M${fmt(start.x)} ${fmt(start.y)}`;
  for (const seg of segments) {
    if (seg.cmd === "L") {
      d += ` L${fmt(seg.to.x)} ${fmt(seg.to.y)}`;
    } else {
      d += ` C${fmt(seg.cp1.x)} ${fmt(seg.cp1.y)} ${fmt(seg.cp2.x)} ${fmt(seg.cp2.y)} ${fmt(seg.to.x)} ${fmt(seg.to.y)}`;
    }
  }
  return d;
}

// Reverses a single M/C/L stroke so it draws tail-first instead of
// head-first (used for the couple of strokes in DRAW_ORDER below that
// connect more smoothly that way).
function reverseStrokeD(d: string): string {
  const { start, segments } = parseSegments(d);
  const anchors = [start, ...segments.map((s) => s.to)];
  const revAnchors = anchors.slice().reverse();
  const revSegments: Segment[] = [];
  for (let i = segments.length - 1; i >= 0; i--) {
    const seg = segments[i];
    const to = revAnchors[segments.length - i];
    if (seg.cmd === "L") {
      revSegments.push({ cmd: "L", to });
    } else {
      revSegments.push({ cmd: "C", cp1: seg.cp2, cp2: seg.cp1, to });
    }
  }
  return buildD(revAnchors[0], revSegments);
}

function dist(a: Point, b: Point): number {
  return Math.hypot(a.x - b.x, a.y - b.y);
}

// ---- draw order: N -> O -> U -> R, left to right, no backtracking -------
//
// Index = position in the raw file (0-8, in the order `splitIntoStrokes`
// produces them for the current nour.svg). Verified by rendering each
// stroke in a distinct color and matching it to the letter it draws:
//   N: 8
//   O: 0 (entry hook), 7 (main loop), 1 (exit, drawn in reverse)
//   U: 6 (first hump), 2 (second hump)
//   R: 5 (stem, drawn in reverse), 4 (top loop), 3 (tail flourish)
const DRAW_ORDER: { index: number; reversed?: boolean }[] = [
  { index: 8 },                  // N
  { index: 0 },                  // O — entry hook
  { index: 7 },                  // O — main loop
  { index: 1, reversed: true },  // O — exit into U
  { index: 6 },                  // U — first hump
  { index: 2 },                  // U — second hump
  { index: 5, reversed: true },  // R — stem
  { index: 4 },                  // R — top loop
  { index: 3 },                  // R — tail flourish
];

const rawStrokeDs = splitIntoStrokes(fullD);

if (rawStrokeDs.length !== DRAW_ORDER.length) {
  throw new Error(
    `nour.svg: expected ${DRAW_ORDER.length} strokes but found ${rawStrokeDs.length}. ` +
      `The hand-verified DRAW_ORDER in nour-path.ts no longer matches the file and needs ` +
      `to be re-derived (map each stroke to the letter it draws, then re-sequence).`
  );
}

const orderedStrokeDs = DRAW_ORDER.map(({ index, reversed }) =>
  reversed ? reverseStrokeD(rawStrokeDs[index]) : rawStrokeDs[index]
);

// GAP_EPSILON: below this distance, two strokes are treated as already
// touching, so no retrace/jump chunks are inserted between them.
const GAP_EPSILON = 0.01;

// Build the ordered chunk list: for each stroke, a visible forward-draw
// chunk, then — only where a real gap follows it — a visible retrace
// chunk (the same stroke, reversed, going back over ink already on
// screen) and an invisible jump chunk (opacity permanently 0) straight
// to the next stroke's real start point. See point 2 in the header
// comment for why this shape specifically.
function buildChunks(strokeDs: string[]): NourChunk[] {
  const chunks: NourChunk[] = [];

  for (let i = 0; i < strokeDs.length; i++) {
    const d = strokeDs[i];
    const { start, end } = parseSegments(d);
    const len = strokeLength(d);

    // 1. Forward draw — the stroke exactly as it is in nour.svg.
    chunks.push({ d, length: len, visible: true });

    if (i === strokeDs.length - 1) continue; // last stroke, nothing follows

    const nextStart = parseSegments(strokeDs[i + 1]).start;
    if (dist(end, nextStart) <= GAP_EPSILON) continue; // strokes already touch

    // 2. Retrace — same stroke, walked backward from `end` to `start`.
    // Visually this re-inks pixels that are already on screen, so it
    // never looks like new drawing; it just reads as the pen backing up.
    const retraceD = reverseStrokeD(d);
    chunks.push({ d: retraceD, length: len, visible: true });

    // 3. Invisible jump — from this stroke's own start (where the
    // retrace just ended) to the next stroke's real start. Always
    // rendered at opacity 0, so however its timing lines up relative to
    // its neighbors, nothing is ever visibly drawn across the gap.
    //
    // NOTE: jumpDist is measured from `start`, not `end` — after the
    // retrace, that's where the pen actually is. `start` can legitimately
    // sit at (or extremely near) `nextStart` even when `end` doesn't, so
    // this needs its own epsilon check. Skipping it when near-zero isn't
    // just an optimization: a zero-length "d" (M and L to the same point)
    // has a real getTotalLength() of 0, and animating pathLength on a
    // zero-length path with framer-motion produces NaN internally, which
    // was the actual cause of the "Maximum call stack size exceeded"
    // crash — Framer's animation loop never converges on NaN and spins.
    const jumpDist = dist(start, nextStart);
    if (jumpDist > GAP_EPSILON) {
      const jumpD = buildD(start, [{ cmd: "L", to: nextStart }]);
      chunks.push({ d: jumpD, length: jumpDist, visible: false });
    }
  }

  return chunks.filter((c) => c.length > GAP_EPSILON);
}

export const NOUR_CHUNKS: NourChunk[] = buildChunks(orderedStrokeDs);

// ---- tight viewBox, derived from the actual artwork ----------------------
//
// The <svg> tag's own viewBox is often just the export canvas (e.g. a
// full A4 page), not the artwork's bounds — that was silently making the
// boot animation draw a small glyph inside a mostly-empty frame. Compute
// the real bounding box from every point in the path instead, with a
// little padding for the stroke width.

const PADDING = 6;

function computeTightViewBox(d: string, strokeWidth: number): string {
  const nums = (s: string) => (s.match(/-?\d*\.?\d+(?:[eE][-+]?\d+)?/g) ?? []).map(Number);
  const tokens = d.match(/[MCL][^MCL]*/g) ?? [];
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const tok of tokens) {
    const n = nums(tok.slice(1));
    for (let i = 0; i + 1 < n.length; i += 2) {
      minX = Math.min(minX, n[i]);
      maxX = Math.max(maxX, n[i]);
      minY = Math.min(minY, n[i + 1]);
      maxY = Math.max(maxY, n[i + 1]);
    }
  }
  const pad = PADDING + strokeWidth;
  minX -= pad; minY -= pad; maxX += pad; maxY += pad;
  return `${fmt(minX)} ${fmt(minY)} ${fmt(maxX - minX)} ${fmt(maxY - minY)}`;
}

export const NOUR_STROKE_WIDTH = rawStrokeWidth ? parseFloat(rawStrokeWidth) : 1.265;

export const NOUR_VIEWBOX = computeTightViewBox(fullD, NOUR_STROKE_WIDTH);

export const NOUR_PATH_D = fullD;